/usr/bin/bash -lc "node <<'NODE'
const fs = require('fs');
const path = require('path');

const root = process.cwd();
const plan = JSON.parse(fs.readFileSync('.exp_agent/round_01/plan.json', 'utf8'));

function filesFor(fragment) {
  const out = new Set();
  for (const rule of plan.rules) {
    if (rule.rule.includes(fragment)) {
      for (const file of rule.files) out.add(file.relative_path);
    }
  }
  return out;
}

function locationsFor(fragment) {
  const out = new Map();
  for (const rule of plan.rules) {
    if (rule.rule.includes(fragment)) {
      for (const file of rule.files) {
        if ("'!out.has(file.relative_path)) out.set(file.relative_path, []);
        for (const loc of file.locations) out.get(file.relative_path).push(loc.line);
      }
    }
  }
  return out;
}

function readLines(rel) {
  return fs.readFileSync(path.join(root, rel), '"'utf8').split('\\n');
}

function writeLines(rel, lines) {
  fs.writeFileSync(path.join(root, rel), lines.join('\\n'));
}

const stateLocations = locationsFor('state-var');
for (const [rel, lineNumbers] of stateLocations) {
  const lines = readLines(rel);
  for (const lineNumber of [...new Set(lineNumbers)].sort((a, b) => b - a)) {
    const index = lineNumber - 1;
    if ("'!/@State'"\\s+/.test(lines[index])) {
      throw new Error('Expected @State at ' + rel + ':' + lineNumber + ': ' + lines[index]);
    }
    lines[index] = lines[index].replace('@State\\s+', '');
  }
  writeLines(rel, lines);
}

const reusableLocations = locationsFor('use-reusable');
for (const [rel, lineNumbers] of reusableLocations) {
  const lines = readLines(rel);
  for (const lineNumber of [...lineNumbers].sort((a, b) => b - a)) {
    const start = lineNumber - 1;
    const original = lines[start];
    const match = original.match(/"'^('"\\s*)Text\\(/);
    if ("'!match) {
      throw new Error('"'Expected Text at ' + rel + ':' + lineNumber + ': ' + original);
    }
    const indent = match[1];
    lines.splice(start, 1,
      indent + 'ReusableLazyItem() {',
      indent + '  ' + original.slice(indent.length)
    );
    let close = -1;
    for (let i = start + 2; i < lines.length; i++) {
      if (/"'^'"\\s*\\},\\s*\\(item/.test(lines[i]) || /"'^'"\\s*\\}\\)\\s*"'$/.test(lines[i])) {
        close = i;
        break;
      }
    }
    if (close === -1) {
      throw new Error('"'Could not find LazyForEach callback close for ' + rel + ':' + lineNumber);
    }
    lines.splice(close, 0, indent + '}');
  }
  writeLines(rel, lines);
}

for (const rel of reusableLocations.keys()) {
  const filePath = path.join(root, rel);
  let source = fs.readFileSync(filePath, 'utf8');
  if ("'!source.includes('"'utils/ReusableLazyItem')) {
    const importPath = path.posix.relative(
      path.posix.dirname(rel),
      'entry/src/main/ets/MainAbility/utils/ReusableLazyItem'
    );
    const modulePath = importPath.startsWith('.') ? importPath : './' + importPath;
    source = \"import { ReusableLazyItem } from '\" + modulePath + \"';\\n\" + source;
    fs.writeFileSync(filePath, source);
  }
}

function matchingBrace(source, open) {
  let depth = 0;
  let quote = null;
  let lineComment = false;
  let blockComment = false;
  const backtick = String.fromCharCode(96);
  for (let i = open; i < source.length; i++) {
    const c = source[i];
    const n = source[i + 1];
    if (lineComment) {
      if (c === '\\n') lineComment = false;
      continue;
    }
    if (blockComment) {
      if (c === '*' && n === '/') {
        blockComment = false;
        i++;
      }
      continue;
    }
    if (quote) {
      if (c === '\\\\') {
        i++;
      } else if (c === quote) {
        quote = null;
      }
      continue;
    }
    if (c === '/' && n === '/') {
      lineComment = true;
      i++;
      continue;
    }
    if (c === '/' && n === '*') {
      blockComment = true;
      i++;
      continue;
    }
    if (c === \"'\" || c === '\"' || c === backtick) {
      quote = c;
      continue;
    }
    if (c === '{') depth++;
    if (c === '}' && --depth === 0) return i;
  }
  throw new Error('No matching brace at offset ' + open);
}

function controlBlocks(source) {
  const blocks = [];
  const re = /\\b(Swiper|List)\\s*\\(["'^'"\\n]*\\)\\s*\\{/g;
  let match;
  while ((match = re.exec(source)) "'!== null) {
    const lineStart = source.lastIndexOf('"'\\n', match.index) + 1;
    const nextNewline = source.indexOf('\\n', match.index);
    const line = source.slice(lineStart, nextNewline === -1 ? source.length : nextNewline);
    const open = lineStart + line.lastIndexOf('{');
    const close = matchingBrace(source, open);
    blocks.push({
      name: match[1],
      open: open,
      close: close,
      indent: (line.match(/"'^('"\\s*)/) || [''])[1]
    });
  }
  return blocks;
}

const cacheFiles = filesFor('set-cache-count');
const animationFiles = filesFor('use-onAnimationStart');
const allAttributeFiles = new Set([...cacheFiles, ...animationFiles]);

for (const rel of allAttributeFiles) {
  const filePath = path.join(root, rel);
  let source = fs.readFileSync(filePath, 'utf8');
  const blocks = controlBlocks(source)
    .filter(block => source.slice(block.open, block.close).includes('LazyForEach('))
    .filter(block => cacheFiles.has(rel) || (animationFiles.has(rel) && block.name === 'Swiper'));

  const operations = [];
  for (const block of blocks) {
    const lineEnd = source.indexOf('\\n', block.close);
    let cursor = lineEnd === -1 ? source.length : lineEnd + 1;
    let chain = '';
    while (cursor < source.length) {
      const nextEnd = source.indexOf('\\n', cursor);
      const nextLine = source.slice(cursor, nextEnd === -1 ? source.length : nextEnd);
      if (/"'^'"\\s*\\./.test(nextLine) || /"'^'"\\s*"'$/.test(nextLine)) {
        chain += nextLine + '"'\\n';
        cursor = nextEnd === -1 ? source.length : nextEnd + 1;
      } else {
        break;
      }
    }
    const additions = [];
    if (cacheFiles.has(rel) && "'!chain.includes('"'.cachedCount(')) {
      additions.push(block.indent + '.cachedCount(2)');
    }
    if (animationFiles.has(rel) && block.name === 'Swiper' && "'!chain.includes('"'.onAnimationStart(')) {
      additions.push(
        block.indent + '.onAnimationStart((index: number, targetIndex: number, extraInfo: SwiperAnimationEvent) => {',
        block.indent + '  console.info(targetIndex.toString())',
        block.indent + '})'
      );
    }
    if (additions.length > 0) {
      operations.push({ offset: block.close + 1, text: '\\n' + additions.join('\\n') });
    }
  }

  for (const op of operations.sort((a, b) => b.offset - a.offset)) {
    source = source.slice(0, op.offset) + op.text + source.slice(op.offset);
  }

  if (animationFiles.has(rel)) {
    source = source.replace(
      /\\.onAnimationStart\\(\\(index: number\\) => \\{/g,
      '.onAnimationStart((index: number, targetIndex: number, extraInfo: SwiperAnimationEvent) => {'
    );
  }
  fs.writeFileSync(filePath, source);
}
