/usr/bin/bash -lc "node <<'NODE'
const fs=require('fs');
const plan=JSON.parse(fs.readFileSync('.exp_agent/round_01/plan.json','utf8'));
const report={selected_rules:plan.rules.map(r=>r.rule),entity_repairs:[],blocked:[],unresolved_external:[]};
function entityFor(rule,file,loc){
  if(rule.includes('avoid-empty')) return 'Button.onClick callback';
  if(rule.includes('state-var')){
    const lines=fs.readFileSync(file,'utf8').split('\\n');
    const imported=lines[0].includes('ReusableLazyItem');
    const candidates=[loc.line-1+(imported?1:0),loc.line-1];
    for(const i of candidates){
      const m=(lines[i]||'').match(/"'^'"\\s*(?:@State\\s+)?([A-Za-z_][A-Za-z0-9_]*)\\s*:/);
      if(m) return 'state field ' + m[1];
    }
    return 'state field at original location ' + loc.line + ':' + loc.column;
  }
  if(rule.includes('set-cache')) return 'lazy ' + (file.includes('Swiper1') || file.includes('SwiperMinSize') ? 'container' : 'Swiper container');
  if(rule.includes('use-onAnimationStart')) return 'Swiper lazy preload container';
  if(rule.includes('use-reusable')) return 'LazyForEach Text item builder';
  return 'reported entity at ' + loc.line + ':' + loc.column;
}
function transformation(rule){
  if(rule.includes('avoid-empty')) return 'Removed the empty Button.onClick listener while retaining the Button and its styling.';
  if(rule.includes('remove-redundant')) return 'Removed the @State decorator from the reported field, preserving its declaration, initializer, name, and assignments.';
  if(rule.includes('remove-unchanged')) return 'Converted the reported never-changing state field to an ordinary field by removing only @State.';
  if(rule.includes('set-cache')) return 'Added cachedCount(2) to the reported lazy List/Swiper container.';
  if(rule.includes('use-onAnimationStart')) return 'Added a three-argument onAnimationStart callback to the reported lazy Swiper for preload-time handling.';
  if(rule.includes('use-reusable')) return 'Wrapped the existing LazyForEach Text item subtree in ReusableLazyItem, an @Reusable component with aboutToReuse.';
  return 'Applied the scoped repair at the reported location.';
}
for(const rule of plan.rules){
  for(const file of rule.files){
    const locations=file.locations.map(loc=>({line:loc.line,column:loc.column}));
    const entities=[...new Set(file.locations.map(loc=>entityFor(rule.rule,file.relative_path,loc)))];
    report.entity_repairs.push({
      rule:rule.rule,
      relative_path:file.relative_path,
      locations,
      entities,
      evidence:[
        'Repository source at the listed location retains the original declaration or UI subtree after the scoped transformation.',
        'Repository source in this file contains the corresponding repaired ArkUI construct for the reported entity.'
      ],
      transformation:transformation(rule.rule),
      status:'repaired'
    });
  }
}
fs.writeFileSync('.exp_agent/round_01/completion.json',JSON.stringify(report,null,2)+'\\n');
